    if (!a.S.authed) return { body: h + '<div style="padding:0 16px">' + a.btn(L('Đăng nhập', 'Sign in'), 'go', { id: 'login' }) + '</div>' };
    var g = function (items) { return '<div class="sec" style="margin-top:14px"><div class="list">' + items.map(function (i) { return '<button type="button" class="li' + (i[3] ? ' dz' : '') + '" data-act="' + (i[4] || 'go') + '" data-id="' + i[0] + '">' + ic(i[1], 'lead') + '<span class="grow">' + i[2] + '</span>' + (i[5] ? '<span class="val">' + i[5] + '</span>' : '') + ic('caret-right', 'chev') + '</button>'; }).join('') + '</div></div>'; };
    h += g([['addrs', 'map-pin', L('Sổ địa chỉ', 'Address book'), 0, 'go', a.S.addrs.length], ['txns', 'receipt', L('Lịch sử giao dịch', 'Transaction history')], ['sessions', 'device-mobile', L('Thiết bị đăng nhập', 'Signed-in devices'), 0, 'go', a.S.sessions.length]]);
    h += g([['langs', 'translate', L('Ngôn ngữ và khu vực', 'Language & region'), 0, 'sheetLang', (a.S.lang ? 'English' : 'Tiếng Việt') + ' · TP.HCM'], ['notifset', 'bell', L('Cài đặt thông báo', 'Notification settings')], ['help', 'lifebuoy', L('Trợ giúp và liên hệ', 'Help & contact')], ['terms', 'file-text', L('Điều khoản và quyền riêng tư', 'Terms & privacy')]]);
    h += g([['logout', 'sign-out', L('Đăng xuất', 'Sign out'), 0, 'logout'], ['delete', 'trash', L('Xoá tài khoản', 'Delete account'), 1, 'sheetDelete']]);
    return { body: h + '<p class="sm-muted" style="text-align:center;margin:18px 0 24px">VN Group · ' + L('phiên bản', 'version') + ' 1.0.0 (MVP)</p>' };
